locals.example:
// Inside child table event trigger in client script:
frappe.ui.form.on("Sales Order Item", {
    rate(frm, cdt, cdn) {
        // 1. Fetch current child table row from locals:
        const row = locals[cdt][cdn];

        // 2. Calculate row amount:
        const amount = (row.qty || 0) * (row.rate || 0);

        // 3. Update field using frappe.model.set_value:
        frappe.model.set_value(cdt, cdn, "amount", amount);
    },
    qty(frm, cdt, cdn) {
        const item = locals[cdt][cdn];
        if (item.qty < 0) {
            frappe.msgprint(__("Quantity cannot be negative"));
            frappe.model.set_value(cdt, cdn, "qty", 0);
        }
    }
});

