frappe.ui.Dialog.example:
const d = new frappe.ui.Dialog({
    title: __("Enter Reason"),
    fields: [{ fieldname: "reason", fieldtype: "Data", label: "Reason", reqd: 1 }],
    primary_action_label: __("Submit"),
    primary_action(values) {
        console.log(values);
        d.hide();
    }
});
d.show();

const values = d.get_values();
if (values) {
    console.log("User entered:", values.reason);
}

d.set_primary_action(__("Confirm"), function() {
    const values = d.get_values();
    if (values) {
        // Handle submission
        d.hide();
    }
});

frappe.realtime.example:
// Listen for real-time task completion broadcast from backend worker:
frappe.realtime.on("import_progress", function(data) {
    frappe.show_progress(__("Importing Customers"), data.current, data.total, data.message);
    if (data.current === data.total) {
        frappe.show_alert({ message: __("Import Finished!"), indicator: "green" });
        cur_frm.reload_doc();
    }
});

frappe.ui.form.example:
// 1. Parent DocType handlers:
frappe.ui.form.on("Customer", {
    refresh(frm) {
        if (frm.is_new()) {
            frm.set_intro(__("Please fill all required business registration details."), "blue");
        }
    },
    customer_type(frm) {
        frm.toggle_reqd("tax_id", frm.doc.customer_type === "Company");
    }
});

// 2. Child Table handlers:
frappe.ui.form.on("Sales Order Item", {
    items_add(frm, cdt, cdn) {
        frappe.msgprint(__("New item row added!"));
    },
    rate(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, "amount", (row.qty || 0) * (row.rate || 0));
    }
});
